<?php require '../config/database.php';auth();$id=(int)($_GET['id']??0);$s=$pdo->prepare("SELECT r.*,c.name customer,c.phone,t.name technician FROM repairs r JOIN customers c ON c.id=r.customer_id LEFT JOIN technicians t ON t.id=r.technician_id WHERE r.id=?");$s->execute([$id]);$r=$s->fetch();if(!$r)die('غير موجود');?><!doctype html><html lang="ar" dir="rtl"><meta charset="utf-8"><link rel="stylesheet" href="../assets/css/style.css"><main><h1>تفاصيل الصيانة #<?=$r['id']?></h1><p>العميل: <?=htmlspecialchars($r['customer'])?></p><p>الهاتف: <?=htmlspecialchars($r['phone'])?></p><p>الفني: <?=htmlspecialchars($r['technician']??'غير محدد')?></p><p>الجهاز: <?=htmlspecialchars($r['device_type'].' '.$r['device_model'])?></p><p>المشكلة: <?=nl2br(htmlspecialchars($r['problem']))?></p><p>التشخيص: <?=nl2br(htmlspecialchars($r['diagnosis']))?></p><p>الحالة: <?=htmlspecialchars($r['status'])?></p><p>التكلفة: <?=$r['final_cost']?></p><p>المدفوع: <?=$r['paid_amount']?></p><p>المتبقي: <?=max(0,$r['final_cost']-$r['paid_amount'])?></p></main>
